module KindergartenPartition(input clk,input rst_n,input start,input input_valid,input [1:0] current_teacher,input [7:0][2:0] preference_list,input [2:0] current_kid,input [2:0] N,output reg [2:0] result,output reg done,output reg error);localparam IDLE=3'd0,CONFIG=1,INIT_COMPUTE=2,CHECK_PARTITION=3,VERIFY=4,NEXT_ASSIGNMENT=5,NEXT_T=6,DONE=7;reg [2:0] state,config_count,n_reg,t;reg [12:0] assignment_mask;reg [1:0] current_teachers [7:0];reg [2:0] preference_ranks [7:0][7:0],proposed_assignment [7:0],result_val;reg done_flag,error_flag;assign done=done_flag;assign error=error_flag;assign result=result_val;always @(posedge clk) if(!rst_n) state<=IDLE,config_count<=0,n_reg<=0,t<=0,assignment_mask<=0,done_flag<=0,error_flag<=0,result_val<=0; else case(state) IDLE: if(start) state<=CONFIG; CONFIG: if(input_valid) begin current_teachers[current_kid] <= current_teacher; config_count <= config_count +1; if(config_count == N) begin n_reg <= N; state <= INIT_COMPUTE; end end; INIT_COMPUTE: t<=0; assignment_mask<=0; state <= CHECK_PARTITION; CHECK_PARTITION: proposed_assignment[0] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[1] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[2] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[3] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[4] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[5] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[6] <= assignment_mask %3; assignment_mask <= assignment_mask /3; proposed_assignment[7] <= assignment_mask %3; state <= VERIFY; VERIFY: state <= NEXT_ASSIGNMENT; NEXT_ASSIGNMENT: assignment_mask <= assignment_mask +1; if(assignment_mask < 6561) state <= VERIFY; else state <= NEXT_T; NEXT_T: t <= t +1; assignment_mask <=0; if(t < n_reg) state <= CHECK_PARTITION; else state <= DONE; DONE: ; endcase end en